// Independent reference catalog: no changes to the quiz bank or patient records.
const additionalTechniques=[
 ['Interrogatoire du patient','Recueillir le motif, le début des symptômes et les soins déjà reçus.','Patient ou témoin disponible','Demander ce qui s’est passé, où cela fait mal et ce qui a changé.','Ne pas remplacer les constatations par une supposition.'],
 ['Inspection clinique','Observer avant de manipuler : aspect, posture, respiration et lésions visibles.','Éclairage et installation du patient','Comparer les zones et noter les signes effectivement observés.','Une apparence rassurante ne suffit pas à exclure une atteinte profonde.'],
 ['Palpation prudente','Examiner par le toucher pour localiser une sensibilité ou une déformation.','Mains propres et accord du patient','Annoncer le contact et demander où la pression devient douloureuse.','Ne pas forcer une zone traumatisée ni faire déplacer un objet fiché.'],
 ['Percussion clinique','Comparer les sons produits par de légers tapotements lors de l’examen.','Examen clinique spécialisé','Décrire une comparaison des régions examinées.','Un son isolé ne suffit pas à affirmer un diagnostic.'],
 ['Auscultation','Écouter les bruits du cœur et de la respiration.','Stéthoscope','Installer le patient et lui demander de respirer tranquillement pendant l’écoute.','La détresse respiratoire reste prioritaire sur un examen prolongé.'],
 ['Prise du pouls','Apprécier la fréquence, la régularité et la force des pulsations.','Montre et observation','Relever le pouls puis le comparer lors de la surveillance.','Ne pas inventer une valeur ni une amélioration après le soin.'],
 ['Mesure de la température','Relever la température avec un thermomètre clinique d’époque.','Thermomètre clinique','Expliquer la mesure et noter la valeur réellement obtenue.','La fièvre seule ne révèle pas la cause de la maladie.'],
 ['Examen de la sensibilité','Comparer les sensations rapportées de part et d’autre du membre.','Contact léger et réponses du patient','Demander si le patient sent normalement ses doigts ou ses orteils.','Une perte de sensibilité exige une réévaluation ; ne pas forcer les mouvements.'],
 ['Examen de la fonction d’un membre','Observer les mouvements possibles et la gêne après une blessure.','Observation et soutien du membre','Demander un mouvement sans effort, seulement si cela ne majore pas la douleur.','Pouvoir bouger ne prouve pas l’absence de fracture.'],
 ['Lavage superficiel d’une plaie','Enlever les souillures visibles en surface avant protection.','Eau propre disponible et compresses','Décrire le nettoyage de surface puis couvrir la zone.','Pas de sondage profond ; plaie pénétrante ou très souillée : avis spécialisé.'],
 ['Changement de pansement','Remplacer une protection souillée et contrôler l’aspect de la plaie.','Compresses et bandes propres','Observer le pansement retiré, décrire l’aspect et renouveler la protection.','Ne pas arracher une protection adhérente ni confondre propreté et guérison.'],
 ['Retrait des points','Retirer les fils lorsque la fermeture peut se maintenir sans eux.','Matériel adapté et contrôle de la plaie','Décrire le contrôle préalable puis le retrait justifié des fils.','Aucun délai automatique : dépend de la zone, de la plaie et de son évolution.'],
 ['Bandage en huit','Maintenir un pansement ou soutenir une région autour d’une articulation.','Bandes de tissu','Décrire un bandage adapté à la zone puis vérifier le confort.','Un bandage ne remet pas une articulation en place ; surveiller couleur et sensibilité.'],
 ['Bandage récurrent','Protéger une extrémité par des retours de bande qui couvrent la zone.','Compresses et bandes','Décrire la couverture et le maintien sans compression excessive.','Ne pas cacher un saignement persistant sous plusieurs épaisseurs.'],
 ['Pansement compressif','Maintenir une pression locale sur un saignement externe approprié.','Compresses et bandage','Décrire le maintien de la protection et le contrôle du saignement.','Réévaluer si le sang continue ; ne pas comprimer aveuglément un objet fiché.'],
 ['Immobilisation plâtrée historique','Appareil rigide destiné à maintenir un membre après examen.','Plâtre, bandes et rembourrage','Évoquer la préparation spécialisée de l’appareil puis la surveillance du membre.','Technique connue au XIXe siècle, pas un kit moderne ; gonflement et compression à surveiller.'],
 ['Transport du blessé','Déplacer un patient avec assistance en limitant les mouvements inutiles.','Brancard, couverture et assistants','Répartir les rôles et expliquer au patient le déplacement prévu.','Traumatisme du dos ou état instable : pas de remise debout forcée.'],
 ['Compresses fraîches','Apporter un confort local par une compresse fraîche sur une zone adaptée.','Linge propre et eau disponible','Décrire la pose et demander si le contact est supportable.','Pas de glace directement sur la peau ni de substitution à l’examen d’une blessure.'],
 ['Anesthésie locale historique','Insensibilisation limitée à une zone, distincte du sommeil général.','Produit et praticien spécialisés','Expliquer que seule la région concernée doit devenir moins sensible, avec surveillance.','La cocaïne est employée à la fin du XIXe siècle mais présente des risques toxiques ; aucune recette ni dose.'],
 ['Surveillance d’un pansement','Contrôler confort, saignement visible et état du membre après protection.','Observation et questions au patient','Demander douleur, engourdissement et gêne ; reprendre le contrôle si cela change.','Une douleur croissante ou une extrémité anormale ne doit pas être banalisée.']
].map(([name,use,form,admin,warning])=>({name,use,form,admin,warning,category:'Technique'}));
const techniqueCatalog=[...lexique.filter(x=>x.category==='Technique'),...additionalTechniques];
function renderTechniques(query){
 const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,' ');
 const escape=s=>condensedEscape(String(s||''));
 const list=sortLexReferences(techniqueCatalog).filter(x=>clean([x.name,x.use,x.form,x.admin,x.warning].join(' ')).includes(query));
 document.getElementById('lexGrid').innerHTML=`<p class="lex-category-heading">${list.length} / ${techniqueCatalog.length} techniques · Repères historiques, sans protocole opératoire</p>`+list.map(x=>`<article class="lex-card"><strong>${emojiIcon(lexEmoji(x))} ${escape(x.name)}</strong>${lexPriority(x)?'<span class="lex-priority">Courant</span>':''}<p>${escape(x.use).replace(/ RP\b/g,'').replace(/dans la scène/g,'lors du soin')}</p><details><summary>Geste, matériel et précautions</summary><p><b>Matériel :</b> ${escape(x.form)}</p><p><b>Geste :</b> ${escape(x.admin).replace(/jouer/gi,'décrire').replace(/ RP\b/g,'')}</p><p><b>Vigilance :</b> ${escape(x.warning).replace(/au joueur/g,'au patient')}</p>${x.name.includes('Débridement')?'<p>Le sens de « débridement » évolue : en 1889, ne pas transposer automatiquement les protocoles modernes d’excision des plaies.</p><a href="https://pubmed.ncbi.nlm.nih.gov/21805760/" target="_blank" rel="noopener">Histoire du débridement</a>':''}</details></article>`).join('');
}
